import { writeFileSync } from 'node:fs';
import openapiTS, { astToString, UNKNOWN } from 'openapi-typescript';

const SPEC_URL = 'https://api.supabase.com/api/v2-json';
const OUTPUT_PATH = new URL(
  '../src/management-api-v2/types.ts',
  import.meta.url
);

function transform(schemaObject, options) {
  if (options.path?.endsWith('JsonValue_Output')) {
    return UNKNOWN;
  }
  return undefined;
}

const ast = await openapiTS(SPEC_URL, { transform });

const output = `/**
 * This file was auto-generated by openapi-typescript.
 * Do not make direct changes to the file.
 */

${astToString(ast)}`;

writeFileSync(OUTPUT_PATH, output);
